import{_ as s,o as a,c as o,a2 as t}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"User Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"USER_SCRIPTS.md","filePath":"USER_SCRIPTS.md"}'),i={name:"USER_SCRIPTS.md"};function n(r,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="user-scripts" tabindex="-1">User Scripts <a class="header-anchor" href="#user-scripts" aria-label="Permalink to &quot;User Scripts&quot;">​</a></h1><p>The scripts in <code>user_scripts/</code> are for anyone using llamatron, as opposed to the development tools in <code>internal_tools/</code>. Each is plain <code>sh</code>, so it needs nothing installed first, and each runs from the project folder wherever it is started, passing on any options it is given. Run one from the project folder as <code>sh user_scripts/NAME.sh</code>.</p><p>Each script below has an example of running it and a list of its parameters, in the order they are given: first what the script is given in place, such as the set to record, and then its options, which may come in any order.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="setup-sh" tabindex="-1"><code>setup.sh</code> <a class="header-anchor" href="#setup-sh" aria-label="Permalink to &quot;`setup.sh`&quot;">​</a></h3><p>Makes the Python virtual environment in <code>.venv</code> and installs llamatron into it. Run it once after cloning the repository, and again if the environment is ever deleted. <a href="./INSTALLING">Installing</a> describes the installation.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/setup.sh</span></span></code></pre></div><p>Parameters: none.</p><h3 id="install-fluidsynth-sh" tabindex="-1"><code>install_fluidsynth.sh</code> <a class="header-anchor" href="#install-fluidsynth-sh" aria-label="Permalink to &quot;`install_fluidsynth.sh`&quot;">​</a></h3><p>Installs FluidSynth, a free software synthesizer, and the sounds it plays, using Homebrew and offering to install Homebrew first. Run it once if you want to hear the demos with no synthesizer or DAW, or to export WAV files. It installs nothing without asking, and does nothing that is already done. See <a href="./FLUIDSYNTH">FluidSynth</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_fluidsynth.sh</span></span></code></pre></div><p>Parameters: none.</p><p>Environment:</p><ul><li><code>SOUNDFONT_DIR</code>: the folder to download the SoundFont into, <code>~/soundfonts</code> unless given. llamatron looks for the SoundFont in <code>~/soundfonts</code>.</li></ul><h3 id="install-blackhole-sh" tabindex="-1"><code>install_blackhole.sh</code> <a class="header-anchor" href="#install-blackhole-sh" aria-label="Permalink to &quot;`install_blackhole.sh`&quot;">​</a></h3><p>Installs BlackHole 2ch, the loopback audio device the demo recorder records sound from, using Homebrew and asking before installing. Run it once before recording your first video. See <a href="./INSTALLING_RECORDING">Recording</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_blackhole.sh</span></span></code></pre></div><p>Parameters: none.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><h3 id="launch-docs-sh" tabindex="-1"><code>launch_docs.sh</code> <a class="header-anchor" href="#launch-docs-sh" aria-label="Permalink to &quot;`launch_docs.sh`&quot;">​</a></h3><p>Serves the documentation website, as committed in <code>web_docs/</code>, on this computer and opens it in the browser. Use it to read the documentation offline, or to check the website after rebuilding it, before publishing. <code>Ctrl+C</code> stops it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/launch_docs.sh</span></span>\n<span class="line"><span>sh user_scripts/launch_docs.sh --port 8080 --no-browser</span></span></code></pre></div><p>Parameters:</p><ul><li><code>--port PORT</code>: the port to serve on, 4173 unless given.</li><li><code>--no-browser</code>: serve without opening the browser.</li></ul><h2 id="listening-to-the-demos" tabindex="-1">Listening to the Demos <a class="header-anchor" href="#listening-to-the-demos" aria-label="Permalink to &quot;Listening to the Demos&quot;">​</a></h2><h3 id="demos-to-midi-sh" tabindex="-1"><code>demos_to_midi.sh</code> <a class="header-anchor" href="#demos-to-midi-sh" aria-label="Permalink to &quot;`demos_to_midi.sh`&quot;">​</a></h3><p>Exports every example as one General MIDI file in <code>previews/</code>, playable in any MIDI player, such as GarageBand. Use it to hear the demos on a computer without llamatron, or to share them.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_midi.sh</span></span>\n<span class="line"><span>sh user_scripts/demos_to_midi.sh examples/learning/13_classic_strum.yml</span></span></code></pre></div><p>Parameters:</p><ul><li><code>SET ...</code>: the sets to export, every example unless given.</li></ul><h3 id="demos-to-wavs-sh" tabindex="-1"><code>demos_to_wavs.sh</code> <a class="header-anchor" href="#demos-to-wavs-sh" aria-label="Permalink to &quot;`demos_to_wavs.sh`&quot;">​</a></h3><p>Turns every demo into a WAV file in <code>previews/</code> in one go: it makes the previews first, plays each through FluidSynth, which it installs the first time, and evens out their loudness. Use it to have every demo as audio to play or share. See <a href="./LISTENING_TO_DEMOS">Listening to the Demos</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_wavs.sh</span></span>\n<span class="line"><span>sh user_scripts/demos_to_wavs.sh previews/classic_strum.mid</span></span></code></pre></div><p>Parameters:</p><ul><li><code>PREVIEW ...</code>: the preview MIDI files to turn into WAV files; every demo, its preview made afresh, unless given.</li></ul><h3 id="play-demo-sh" tabindex="-1"><code>play_demo.sh</code> <a class="header-anchor" href="#play-demo-sh" aria-label="Permalink to &quot;`play_demo.sh`&quot;">​</a></h3><p>Plays a demo&#39;s WAV file in the terminal, by its number in the list or its name, after saying its number and what the demo is: the set, its title, genre and description. Use it after <code>demos_to_wavs.sh</code> to listen without opening the tracker.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/play_demo.sh</span></span>\n<span class="line"><span>sh user_scripts/play_demo.sh --list</span></span>\n<span class="line"><span>sh user_scripts/play_demo.sh 12</span></span>\n<span class="line"><span>sh user_scripts/play_demo.sh classic_strum</span></span></code></pre></div><p>Parameters:</p><ul><li><code>DEMO</code>: the demo to play, by its number in the list, by its name, such as <code>classic_strum</code>, or by the path of a WAV file; a numbered list to pick from unless given.</li><li><code>--list</code>: print the numbered list and play nothing.</li><li><code>--folder FOLDER</code>: where the WAV files are, <code>previews/</code> unless given.</li></ul><h3 id="demos-to-live-sets-sh" tabindex="-1"><code>demos_to_live_sets.sh</code> <a class="header-anchor" href="#demos-to-live-sets-sh" aria-label="Permalink to &quot;`demos_to_live_sets.sh`&quot;">​</a></h3><p>Exports every example as an Ableton Live set beside it, replacing earlier exports. Use it to open the demos in Live with every scene and clip in place.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demos_to_live_sets.sh</span></span></code></pre></div><p>Parameters: none.</p><h2 id="demo-information" tabindex="-1">Demo Information <a class="header-anchor" href="#demo-information" aria-label="Permalink to &quot;Demo Information&quot;">​</a></h2><h3 id="demo-report-sh" tabindex="-1"><code>demo_report.sh</code> <a class="header-anchor" href="#demo-report-sh" aria-label="Permalink to &quot;`demo_report.sh`&quot;">​</a></h3><p>Prints a report of the demos as comma-separated values, for a spreadsheet: one row per demo with its genre, what it plays, its length, scenes, tracks and the features it uses, or with <code>--features</code> one row per feature and a column per demo. Use it to find a demo that shows a feature, or to sort and filter the demos.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/demo_report.sh &gt; demos.csv</span></span>\n<span class="line"><span>sh user_scripts/demo_report.sh --features &gt; features.csv</span></span>\n<span class="line"><span>sh user_scripts/demo_report.sh examples/by_genre/electronic/*.yml</span></span></code></pre></div><p>Parameters:</p><ul><li><code>--features</code>: one row per feature and a column per demo, rather than one row per demo. Given first.</li><li><code>SET ...</code>: the sets to report on, every example unless given.</li></ul><h2 id="recording-videos" tabindex="-1">Recording Videos <a class="header-anchor" href="#recording-videos" aria-label="Permalink to &quot;Recording Videos&quot;">​</a></h2><p>Every recording script needs the setup that <a href="./INSTALLING_RECORDING">Recording</a>, under Installing, describes: BlackHole, Screen Recording permission for your terminal, and Xcode&#39;s command line tools. <a href="./RECORDING">Recording</a> describes the takes themselves.</p><p>The visualizer modes a recording can show are <code>lava_lamp</code>, <code>piano_roll</code>, <code>spectrum</code>, <code>milkdrop</code>, <code>llamas</code>, <code>hypercube</code>, <code>fireworks</code>, <code>warpzone</code>, <code>pipes</code>, <code>plasma</code>, <code>maze</code>, <code>mystify</code>, <code>laser_llama</code>, <code>mandelbrot</code>, <code>life</code>, <code>digital_rain</code> and <code>cycle</code>.</p><h3 id="record-sh" tabindex="-1"><code>record.sh</code> <a class="header-anchor" href="#record-sh" aria-label="Permalink to &quot;`record.sh`&quot;">​</a></h3><p>Records a video of the tracker playing a set on Arrange. <code>--sound</code> says where the sound comes from: <code>daw</code>, the default, plays the set&#39;s tracks over MIDI into your DAW, so the song sounds as your own instruments play it, and <code>fluidsynth</code> plays the set&#39;s own FluidSynth instruments, so no DAW is needed, the simplest recording. With <code>--interactive</code> you perform the take: nothing plays until you press <code>Space</code> on Arrange&#39;s corner, and stopping there, or <code>Esc</code>, ends it, so that you can launch scenes and edit as the song plays. A take of a visualizer opens on the title and READY and fills the screen with the visualizer in its frame, unless <code>--plain</code> is given.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth</span></span>\n<span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth --visualizer plasma --go</span></span>\n<span class="line"><span>sh user_scripts/record.sh examples/learning/01_hello_world.yml --sound fluidsynth --interactive</span></span>\n<span class="line"><span>sh user_scripts/record.sh my_set.yml --use-driver &quot;My Synth&quot; --track-assign 1,1,2 --max-seconds 60</span></span>\n<span class="line"><span>sh user_scripts/record.sh my_set.yml --interactive --use-driver &quot;IAC&quot;</span></span></code></pre></div><p>Parameters:</p><ul><li><code>SET</code>: the set to record, such as <code>examples/learning/01_hello_world.yml</code>.</li><li><code>--sound SOUND</code>: <code>daw</code>, the default, or <code>fluidsynth</code>.</li><li><code>--interactive</code>: perform the take yourself.</li><li><code>--visualizer MODE</code>: record this visualizer mode rather than the clips.</li><li><code>--clips</code>: record the clips on Arrange, without asking.</li><li><code>--plain</code>: with <code>--visualizer</code>, show the visualizer over Arrange&#39;s clip area, the older style, rather than the title, READY and the framed visualizer.</li><li><code>--no-alternate</code>: show the visualizer alone in the frame, rather than the clips and the visualizer by turns every ten seconds.</li><li><code>--batch</code>: record the take as one of a batch video&#39;s, from the window&#39;s cells alone.</li><li><code>--audio-device DEVICE</code>: the audio input device to record the sound from, the first whose name holds this text.</li><li><code>--max-seconds SECONDS</code>: the longest the take may run.</li><li><code>--window-id ID</code>: the id of the window to record, when the terminal program cannot be asked.</li><li><code>--go</code>: start the take at once, without waiting for Enter after the setup is explained.</li></ul><p>With <code>--sound daw</code>:</p><ul><li><code>--use-driver PORT</code>: the MIDI output port to play through, the first whose name holds this text.</li><li><code>--track-assign-auto</code>: the first track on channel 1, the second on 2 and so on, the default.</li><li><code>--track-assign CHANNELS</code>: a channel for each track in the song&#39;s order, such as <code>1,1,2</code>, with <code>-</code> to keep a track&#39;s own instrument.</li></ul><p>With <code>--sound fluidsynth</code>:</p><ul><li><code>--fluidsynth-output DEVICE</code>: the audio output FluidSynth plays to, such as a Multi-Output Device that reaches the recorded one too; the recorded device unless given.</li></ul><h3 id="record-all-sh" tabindex="-1"><code>record_all.sh</code> <a class="header-anchor" href="#record-all-sh" aria-label="Permalink to &quot;`record_all.sh`&quot;">​</a></h3><p>Records a video of every example through FluidSynth, shortest first, each showing the visualizer mode its pairing gives it, and leaves out any example whose video is already recorded. Use it to make videos of every demo for uploading.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/record_all.sh</span></span>\n<span class="line"><span>LLAMATRON_BATCH_RECORD_MAX=2 sh user_scripts/record_all.sh</span></span></code></pre></div><p>Parameters:</p><ul><li><code>--audio-device DEVICE</code>: the audio input device to record the sound from, the first whose name holds this text.</li><li><code>--fluidsynth-output DEVICE</code>: the audio output FluidSynth plays to, such as a Multi-Output Device that reaches the recorded one too.</li><li><code>--window-id ID</code>: the id of the window to record, when the terminal program cannot be asked.</li><li><code>--go</code>: start at once, without waiting for Enter after the list of takes.</li></ul><p>Environment:</p><ul><li><code>LLAMATRON_BATCH_RECORD_MAX</code>: record only this many examples, the shortest, such as <code>2</code> to try it first.</li></ul>',69)])])}const m=s(i,[["render",n]]);export{u as __pageData,m as default};
